#include <stdio.h>

#define MAX_HASH 1000001

int hashtable[MAX_HASH]; // Map number to its latest index

// Functions to clear and get from hashtable
void clearHashtable() {
    for (int i = 0; i < MAX_HASH; i++)
        hashtable[i] = -1; // Index -1 means the number has not appeared
}

int getHash(int number) {
    if (number >= 0 && number < MAX_HASH) {
        return hashtable[number];
    }
    return -1; // Not found or out of bounds
}

void setHash(int number, int index) {
    if (number >= 0 && number < MAX_HASH) {
        hashtable[number] = index;
    }
}

// Main code to find longest consecutive sequence and print indices
void findLongestConsecutiveSequence(int book[], int n) {
    clearHashtable();
    int longestStreak = 0;
    int startIndex = -1;
    int number;
    int printed = 0; // Flag to check if the longest subsequence has been printed

    for (int i = 0; i < n; i++) {
        setHash(book[i], i);
    }

    for (int i = 0; i < n; i++) {
        number = book[i];
        if (getHash(number - 1) == -1) {  // Potential start of the sequence
            int currentStreak = 1;
            while (getHash(number + currentStreak) != -1) {
                currentStreak++;
            }
            if (currentStreak > longestStreak) {
                longestStreak = currentStreak;
                startIndex = number; // Store the starting number of the streak
            }
        }
    }

    printf("%d\n", longestStreak);
    for (int i = 0; i < longestStreak; i++) {
        printf("%d ", getHash(startIndex + i));
    }

    printed = 1; // Set flag to indicate the longest subsequence has been printed

    return;
}

int main() {
    int n;
    scanf("%d", &n);
    int book[n];

    for (int i = 0; i < n; i++) {
        scanf("%d", &book[i]);
    }

    findLongestConsecutiveSequence(book, n);
    return 0;
}

